//! Debt payoff — which debt to attack first, and what the choice actually costs.
//!
//! Two orderings are in common use and they optimise different things:
//!
//! - **Avalanche** — highest interest RATE first. Mathematically optimal: it always pays the least
//!   total interest and is never slower.
//! - **Snowball** — smallest BALANCE first. Pays more, sometimes much more — but clears whole
//!   accounts sooner, and finishing one is what makes people keep going.
//!
//! This module does not pick for you. It runs both and reports the difference in money and months, so
//! the trade is a NUMBER rather than a slogan. That is the honest framing: snowball's cost is real
//! and so is its benefit, and only the person paying can weigh them.
//!
//! Everything is integer MINOR UNITS. A payoff schedule is exactly where float drift shows up as a
//! final instalment that is a cent off and a total that will not reconcile.
use crate::money::{money, sum, Money, Rounding};

/// One debt, as the payer knows it.
#[derive(Debug, Clone, PartialEq)]
pub struct Debt {
    /// How the payer refers to it — shown back in the schedule.
    pub name: String,
    /// What is owed now.
    pub balance: Money,
    /// NOMINAL annual rate as a fraction: 0.2299 for 22.99% APR.
    pub apr: f64,
    /// The contractual minimum for a period. Paying less is default, so it is never skipped.
    pub minimum: Money,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Strategy {
    Avalanche,
    Snowball,
}

impl Strategy {
    pub fn label(self) -> &'static str {
        match self {
            Strategy::Avalanche => "avalanche",
            Strategy::Snowball => "snowball",
        }
    }
}

/// What happened to one debt in one period.
#[derive(Debug, Clone, PartialEq)]
pub struct Payment {
    pub name: String,
    pub interest: Money,
    pub principal: Money,
    pub balance: Money,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Period {
    /// 1-based; period 1 is the first payment made.
    pub period: usize,
    pub payments: Vec<Payment>,
    /// Debts that reached zero in THIS period — the moment a snowball payer is waiting for.
    pub cleared_this_period: Vec<String>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Plan {
    pub strategy: Strategy,
    pub periods: Vec<Period>,
    /// How many periods until every balance is zero.
    pub months: usize,
    pub total_interest: Money,
    pub total_paid: Money,
    /// Payoff order, in the order each debt actually cleared.
    pub order: Vec<String>,
}

/// Why no schedule exists. A REFUSAL, never a truncated plan that stops at an arbitrary horizon and
/// reads as one.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Unpayable(pub String);

impl std::fmt::Display for Unpayable {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.0)
    }
}

impl std::error::Error for Unpayable {}

/// Periodic rate from a nominal annual rate. 12 periods a year unless stated.
pub fn periodic_rate(apr: f64, periods_per_year: f64) -> f64 {
    apr / periods_per_year
}

pub struct PayoffOptions {
    pub periods_per_year: f64,
    pub max_periods: usize,
}

impl Default for PayoffOptions {
    fn default() -> Self {
        PayoffOptions { periods_per_year: 12.0, max_periods: 1200 }
    }
}

/// The ORDER the strategy attacks in.
///
/// Ties are broken by the other key, then by NAME, so a run is deterministic — two runs of the same
/// input must produce the same schedule or the comparison below is not reproducible.
pub fn payoff_order(debts: &[Debt], strategy: Strategy) -> Vec<Debt> {
    let mut out = debts.to_vec();
    out.sort_by(|a, b| {
        let by_rate = b.apr.partial_cmp(&a.apr).unwrap_or(std::cmp::Ordering::Equal);
        let by_balance = a.balance.minor.cmp(&b.balance.minor);
        let first = match strategy {
            Strategy::Avalanche => by_rate.then(by_balance),
            Strategy::Snowball => by_balance.then(by_rate),
        };
        first.then_with(|| a.name.cmp(&b.name))
    });
    out
}

/// Run one strategy to completion.
///
/// The mechanics, which are the same either way and are what actually retires debt:
///
/// - every debt accrues interest on its balance, then takes at least its minimum;
/// - whatever is left of `monthly_payment` goes ENTIRELY to the target — the first unpaid debt in
///   strategy order;
/// - when a debt clears, its minimum is NOT saved. It rolls into the next target. That rolling is
///   the "snowball", and it is why both strategies accelerate rather than run at a constant rate.
///
/// REFUSES an unpayable plan rather than looping. If the budget cannot cover the minimums, or a
/// balance grows despite paying them, no schedule exists.
pub fn payoff(debts: &[Debt], monthly_payment: Money, strategy: Strategy, opts: &PayoffOptions) -> Result<Plan, Unpayable> {
    if debts.is_empty() {
        return Err(Unpayable("payoff needs at least one debt".to_string()));
    }
    let currency = monthly_payment.currency;

    let mins: Vec<Money> = debts.iter().map(|d| d.minimum).collect();
    let minimums = sum(&mins, currency).map_err(|e| Unpayable(e.to_string()))?;
    if monthly_payment.minor < minimums.minor {
        return Err(Unpayable(format!(
            "the budget cannot cover the minimum payments ({} minor units of {}); a plan that ignores that is not a plan — the shortfall has to be closed first",
            minimums.minor, currency
        )));
    }

    let mut live = payoff_order(debts, strategy);
    let mut periods: Vec<Period> = Vec::new();
    let mut order: Vec<String> = Vec::new();
    let mut total_interest = money(0, currency);
    let mut total_paid = money(0, currency);

    let mut p = 0usize;
    while live.iter().any(|d| d.balance.minor != 0) {
        p += 1;
        if p > opts.max_periods {
            return Err(Unpayable(format!(
                "no payoff within {} periods — at this budget the interest is outrunning the payments, which is a fact worth stating rather than a schedule worth returning",
                opts.max_periods
            )));
        }
        let mut budget = monthly_payment.minor;
        let mut payments: Vec<Payment> = Vec::new();
        let mut cleared: Vec<String> = Vec::new();

        // 1 — interest, then the contractual minimum on every live debt.
        for d in live.iter_mut() {
            if d.balance.minor == 0 {
                continue;
            }
            let interest = crate::money::scale(d.balance, periodic_rate(d.apr, opts.periods_per_year), Rounding::HalfUp);
            let owed = d.balance.minor + interest.minor;
            // Never pay more than clears it, and never less than the minimum — unless the debt is
            // SMALLER than its own minimum, in which case the payoff amount IS the payment.
            let wanted = if d.minimum.minor < owed { d.minimum.minor } else { owed };
            let pay = wanted.min(budget);
            budget -= pay;
            let principal = pay - interest.minor;
            d.balance = money(owed - pay, currency);
            total_interest = money(total_interest.minor + interest.minor, currency);
            total_paid = money(total_paid.minor + pay, currency);
            payments.push(Payment { name: d.name.clone(), interest, principal: money(principal, currency), balance: d.balance });
        }

        // 2 — everything left attacks the TARGET, in strategy order.
        for d in live.iter_mut() {
            if budget == 0 {
                break;
            }
            if d.balance.minor == 0 {
                continue;
            }
            let extra = d.balance.minor.min(budget);
            budget -= extra;
            d.balance = money(d.balance.minor - extra, currency);
            total_paid = money(total_paid.minor + extra, currency);
            if let Some(row) = payments.iter_mut().find(|x| x.name == d.name) {
                row.principal = money(row.principal.minor + extra, currency);
                row.balance = d.balance;
            }
        }

        for d in live.iter() {
            if d.balance.minor == 0 && !order.contains(&d.name) {
                order.push(d.name.clone());
                cleared.push(d.name.clone());
            }
        }
        periods.push(Period { period: p, payments, cleared_this_period: cleared });
    }

    Ok(Plan { strategy, months: periods.len(), periods, total_interest, total_paid, order })
}

/// What choosing snowball over avalanche costs — the number the decision actually turns on.
#[derive(Debug, Clone, PartialEq)]
pub struct Comparison {
    pub avalanche: Plan,
    pub snowball: Plan,
    /// Extra interest snowball pays. Never negative: avalanche is optimal on interest by construction.
    pub extra_interest: Money,
    /// Extra periods snowball takes. Never negative.
    pub extra_months: i64,
    /// How much SOONER snowball clears its first debt — what it buys for that cost.
    pub first_cleared_sooner: i64,
}

pub fn compare_strategies(debts: &[Debt], monthly_payment: Money, opts: &PayoffOptions) -> Result<Comparison, Unpayable> {
    let avalanche = payoff(debts, monthly_payment, Strategy::Avalanche, opts)?;
    let snowball = payoff(debts, monthly_payment, Strategy::Snowball, opts)?;
    let first_cleared = |p: &Plan| -> i64 {
        p.periods.iter().find(|x| !x.cleared_this_period.is_empty()).map(|x| x.period as i64).unwrap_or(p.months as i64)
    };
    Ok(Comparison {
        extra_interest: money(snowball.total_interest.minor - avalanche.total_interest.minor, monthly_payment.currency),
        extra_months: snowball.months as i64 - avalanche.months as i64,
        first_cleared_sooner: first_cleared(&avalanche) - first_cleared(&snowball),
        avalanche,
        snowball,
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::usd;

    // SYNTHETIC FIXTURES ONLY.
    fn d(name: &str, balance: i64, apr: f64, minimum: i64) -> Debt {
        Debt { name: name.to_string(), balance: usd(balance), apr, minimum: usd(minimum) }
    }

    /// The store card has the SMALLEST balance and the LOWEST rate; medical has the HIGHEST rate at a
    /// middling balance. That is what makes the two strategies actually disagree — a fixture where
    /// the smallest debt is also the dearest one proves nothing, and my first one was exactly that.
    fn debts() -> Vec<Debt> {
        vec![d("visa", 300_000, 0.2299, 6_000), d("store", 80_000, 0.0999, 2_500), d("medical", 150_000, 0.2999, 4_000)]
    }

    #[test]
    fn avalanche_attacks_the_dearest_and_snowball_the_smallest() {
        let names = |s: Strategy| payoff_order(&debts(), s).iter().map(|d| d.name.clone()).collect::<Vec<_>>();
        assert_eq!(names(Strategy::Avalanche), vec!["medical", "visa", "store"], "by RATE");
        assert_eq!(names(Strategy::Snowball), vec!["store", "medical", "visa"], "by BALANCE");
    }

    #[test]
    fn the_cost_of_snowball_is_a_number_rather_than_a_slogan() {
        // Measured by running finance-payoff.ts on this exact fixture.
        let c = compare_strategies(&debts(), usd(40_000), &PayoffOptions::default()).expect("payable");
        assert_eq!(c.avalanche.months, 16);
        assert_eq!(c.avalanche.total_interest.minor, 78_043);
        assert_eq!(c.avalanche.total_paid.minor, 608_043);
        assert_eq!(c.snowball.months, 16);
        assert_eq!(c.snowball.total_interest.minor, 91_364);
        // Snowball costs $133.21 more and takes the same time — and clears its first debt three
        // months sooner. Both halves of the trade are reported; neither is chosen here.
        assert_eq!(c.extra_interest.minor, 13_321);
        assert_eq!(c.extra_months, 0);
        assert_eq!(c.first_cleared_sooner, 3);
        assert!(c.extra_interest.minor >= 0, "avalanche is optimal on interest BY CONSTRUCTION");
    }

    #[test]
    fn each_strategy_clears_its_debts_in_its_own_order() {
        let opts = PayoffOptions::default();
        let a = payoff(&debts(), usd(40_000), Strategy::Avalanche, &opts).expect("payable");
        let s = payoff(&debts(), usd(40_000), Strategy::Snowball, &opts).expect("payable");
        assert_eq!(a.order, vec!["medical", "visa", "store"]);
        assert_eq!(s.order, vec!["store", "medical", "visa"]);
        let cleared = |p: &Plan| p.periods.iter().filter(|x| !x.cleared_this_period.is_empty()).map(|x| (x.period, x.cleared_this_period.clone())).collect::<Vec<_>>();
        assert_eq!(cleared(&a), vec![(6, vec!["medical".to_string()]), (14, vec!["visa".to_string()]), (16, vec!["store".to_string()])]);
        assert_eq!(cleared(&s), vec![(3, vec!["store".to_string()]), (8, vec!["medical".to_string()]), (16, vec!["visa".to_string()])]);
    }

    #[test]
    fn the_first_period_pays_every_minimum_then_throws_the_rest_at_the_target() {
        let a = payoff(&debts(), usd(40_000), Strategy::Avalanche, &PayoffOptions::default()).expect("payable");
        let p1: Vec<(&str, i64, i64, i64)> = a.periods[0].payments.iter().map(|x| (x.name.as_str(), x.interest.minor, x.principal.minor, x.balance.minor)).collect();
        // medical is the target, so it takes its own minimum PLUS everything left over.
        assert_eq!(p1, vec![("medical", 3_749, 27_751, 122_249), ("visa", 5_748, 252, 299_748), ("store", 666, 1_834, 78_166)]);
        // Every minimum was still paid: 4000 + 6000 + 2500 = 12500, and the other 27500 went to the
        // target. Skipping a minimum to attack faster is default, not strategy.
        let paid: i64 = a.periods[0].payments.iter().map(|x| x.interest.minor + x.principal.minor).sum();
        assert_eq!(paid, 40_000, "the whole budget is spent, nothing is idle");
    }

    #[test]
    fn a_budget_below_the_minimums_is_refused_rather_than_scheduled() {
        let e = payoff(&debts(), usd(1_000), Strategy::Avalanche, &PayoffOptions::default()).expect_err("unpayable");
        assert!(e.0.contains("cannot cover the minimum payments (12500 minor units of USD)"));
        assert!(e.0.contains("the shortfall has to be closed first"), "it says what to DO");
    }

    #[test]
    fn interest_outrunning_the_payment_is_stated_rather_than_truncated() {
        let opts = PayoffOptions { max_periods: 24, ..PayoffOptions::default() };
        let e = payoff(&[d("runaway", 1_000_000, 0.99, 100)], usd(100), Strategy::Avalanche, &opts).expect_err("unpayable");
        assert!(e.0.contains("no payoff within 24 periods"));
        // A truncated 24-period schedule would LOOK like a plan while being none. That is the whole
        // reason this returns an error rather than the periods it managed to compute.
        assert!(e.0.contains("worth stating rather than a schedule worth returning"));
    }

    #[test]
    fn no_debts_is_refused_because_there_is_nothing_to_schedule() {
        let e = payoff(&[], usd(40_000), Strategy::Avalanche, &PayoffOptions::default()).expect_err("unpayable");
        assert_eq!(e.0, "payoff needs at least one debt");
    }

    #[test]
    fn a_debt_smaller_than_its_own_minimum_pays_only_what_clears_it() {
        // Balance 500, minimum 2500. Paying the minimum would overpay by 2000.
        let p = payoff(&[d("tiny", 500, 0.2, 2_500)], usd(2_500), Strategy::Avalanche, &PayoffOptions::default()).expect("payable");
        assert_eq!(p.months, 1);
        assert_eq!(p.total_interest.minor, 8);
        assert_eq!(p.total_paid.minor, 508, "500 principal + 8 interest, NOT the 2500 minimum");
        let row = &p.periods[0].payments[0];
        assert_eq!((row.interest.minor, row.principal.minor, row.balance.minor), (8, 500, 0));
    }

    #[test]
    fn ties_break_deterministically_so_two_runs_agree() {
        let same = vec![d("b", 50_000, 0.2, 1_000), d("a", 50_000, 0.2, 1_000)];
        assert_eq!(payoff_order(&same, Strategy::Avalanche).iter().map(|d| d.name.clone()).collect::<Vec<_>>(), vec!["a", "b"], "by NAME once rate and balance tie");
        // Equal balances under avalanche fall back to the rate.
        let by_rate = vec![d("hi", 50_000, 0.3, 1_000), d("lo", 50_000, 0.1, 1_000)];
        assert_eq!(payoff_order(&by_rate, Strategy::Avalanche)[0].name, "hi");
        // Equal-ish rates under snowball fall back to the balance.
        let by_balance = vec![d("big", 90_000, 0.3, 1_000), d("small", 10_000, 0.1, 1_000)];
        assert_eq!(payoff_order(&by_balance, Strategy::Snowball)[0].name, "small");
    }

    #[test]
    fn the_periodic_rate_divides_the_nominal_annual_one() {
        assert!((periodic_rate(0.2299, 12.0) - 0.019158333333333333).abs() < 1e-15);
        assert!((periodic_rate(0.2299, 26.0) - 0.008842307692307693).abs() < 1e-15);
    }

    #[test]
    fn the_schedule_reconciles_to_the_cent() {
        // The reason this is integer minor units: principal + interest across every period must
        // equal what was paid, and the balances must reach exactly zero rather than nearly zero.
        let a = payoff(&debts(), usd(40_000), Strategy::Avalanche, &PayoffOptions::default()).expect("payable");
        let principal: i64 = a.periods.iter().flat_map(|p| p.payments.iter()).map(|x| x.principal.minor).sum();
        let interest: i64 = a.periods.iter().flat_map(|p| p.payments.iter()).map(|x| x.interest.minor).sum();
        assert_eq!(interest, a.total_interest.minor);
        assert_eq!(principal + interest, a.total_paid.minor);
        // And the principal repaid equals exactly what was owed at the start.
        assert_eq!(principal, 300_000 + 80_000 + 150_000);
        for p in a.periods.last().expect("periods").payments.iter() {
            assert_eq!(p.balance.minor, 0, "{} did not reach exactly zero", p.name);
        }
    }
}
